/* team-profiles.js — GENERATED by scripts/theme-js.mjs from the repo-root js/team-profiles.js.
 * Do not edit here: edit the source and run `npm run build:theme`.
 * The source IIFE runs once per page inside Drupal.behaviors.iconTeamProfiles.attach()
 * (once() on <html>), so the behaviour body is byte-identical to the prototype's. */
((Drupal, once) => {
  Drupal.behaviors.iconTeamProfiles = {
    attach(context) {
      if (!once("team-profiles", "html", context).length) return;

      /* team-profiles.js — the team panel: open a profile from its card, step
       * previous / next, close by the X, by Escape or by a click beside the panel,
       * and keep the ADDRESS in step with it the whole way.
       *
       * The grid's links point at the panel's own address (/about/<slug>), which
       * the server accepts (icon_site's TeamProfilePathProcessor serves the About
       * page for it), so a link opened in a new tab, or sent to someone, lands
       * here with that address — and this reads it on load and opens the panel.
       * From then on every open, step and close is a pushState, so Back and
       * Forward walk the panels the way the reference site does
       * (basicagency.com/about). The document title follows the person.
       *
       * The panel is a native <dialog> shown modally: focus is held inside, Escape
       * fires `cancel` (intercepted, so the address is written too), and the click
       * beside the panel is a click on the dialog's own transparent box.
       *
       * THE ARRIVING is the site's own (user call, Sep 2026): a profile enters
       * the way a page does — the name on the word cascade, the bio and the link
       * on the rise, the portrait through the media mask — and stepping to the
       * next person is the page move's fade, a same-document View Transition on
       * the portrait and the text (utilities/page-transition.css names them),
       * with the new profile's entrances playing once the fade has landed. The
       * entrances are the shared ones (js/reveal.js, utilities/animations.css,
       * home-c.css): this file only re-arms them — the classes come off while
       * the profile is hidden and go back on a frame after it shows. The
       * portrait tilts toward the cursor through the shared engine
       * (js/cursor-tilt.js), and the grid's cards lean with the scroll through
       * the other one (js/velocity-lean.js). Reduced motion: the CSS drops every one of them and
       * the fade is skipped; the swap is instant.
       * Drupal: Drupal.behaviors.iconTeamProfiles via `icon/team-profiles`
       * (after `icon/reveal`, which splits the names, `icon/cursor-tilt` and
       * `icon/velocity-lean`). */
      (function () {
        "use strict";

        var overlay = document.querySelector("[data-team-overlay]");
        if (!overlay || typeof overlay.showModal !== "function") return;

        var base = overlay.getAttribute("data-team-base") || "/about";
        var profiles = Array.prototype.slice.call(overlay.querySelectorAll("[data-team-profile]"));
        var slugs = profiles.map(function (p) { return p.getAttribute("data-team-profile"); });
        if (!slugs.length) return;
        var indexEl = overlay.querySelector("[data-team-index]");
        var closeBtn = overlay.querySelector("[data-team-close]");
        var prevBtn = overlay.querySelector("[data-team-prev]");
        var nextBtn = overlay.querySelector("[data-team-next]");
        var pageTitle = document.title;
        var siteName = (pageTitle.split(" — ").pop() || "").trim();
        var current = -1;
        var panel = overlay.firstElementChild;
        var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
        var fluid = typeof document.startViewTransition === "function" && !reduce;
        // The address is written where it can be: inside the Canvas editor's
        // preview frame (about:srcdoc) the history is not ours to write, and the
        // browser throws — the panel still opens, the address simply stays.
        var go = function (how, state, title, url) {
          try { history[how](state, title, url); } catch (err) {}
        };
        var deepLink = new RegExp("^" + base.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "/([a-z0-9-]+)/?$");

        function pad(n) { return (n < 10 ? "0" : "") + n; }

        var REVEALS = "[data-animate], [data-reveal-words], [data-reveal-img]";
        function revealClass(el) {
          return el.hasAttribute("data-animate") ? "is-visible" : "is-revealed";
        }
        // back to the start of every entrance, while the profile is hidden
        function arm(profile) {
          Array.prototype.slice.call(profile.querySelectorAll(REVEALS)).forEach(function (el) {
            el.classList.remove(revealClass(el));
          });
        }
        // and off they go — a frame later, from a computed start state, or the
        // browser sees only the end and nothing moves
        function play(profile) {
          requestAnimationFrame(function () {
            void panel.offsetWidth;
            Array.prototype.slice.call(profile.querySelectorAll(REVEALS)).forEach(function (el) {
              el.classList.add(revealClass(el));
            });
          });
        }

        function show(i) {
          var next = profiles[i];
          var change = function () {
            profiles.forEach(function (p, k) { p.hidden = k !== i; });
            if (indexEl) indexEl.textContent = pad(i + 1);
            var name = next.querySelector("[data-team-name]");
            document.title = name && siteName ? name.textContent.trim() + " — " + siteName : pageTitle;
            // the panel scrolls; a new person starts at the top of it
            panel.scrollTop = 0;
          };
          // the entrances wait for the panel's own slide on an open, not on a step
          panel.style.setProperty("--animate-hold", overlay.open ? "0ms" : "250ms");
          arm(next);
          if (fluid && overlay.open && current >= 0 && current !== i) {
            document.startViewTransition(change).finished.finally(function () { play(next); });
          } else {
            change();
            play(next);
          }
          current = i;
        }

        function open(slug, push) {
          var i = slugs.indexOf(slug);
          if (i < 0) return false;
          show(i);
          if (!overlay.open) {
            // the scrollbar's width, measured before the lock takes it away, for
            // the CSS fallback that pads the page by it (scrollbar-gutter does
            // the same on its own where it is supported)
            var root = document.documentElement;
            root.style.setProperty("--team-scrollbar", (window.innerWidth - root.clientWidth) + "px");
            overlay.showModal();
            root.classList.add("is-team-open");
          }
          if (push) go("pushState", { team: slug }, "", base + "/" + slug);
          if (closeBtn) closeBtn.focus();
          return true;
        }

        function close(push) {
          if (!overlay.open) return;
          overlay.close();
          document.documentElement.classList.remove("is-team-open");
          document.title = pageTitle;
          if (push) go("pushState", { team: null }, "", base);
          // hand focus back to the card that was opened
          if (current >= 0) {
            var link = document.querySelector('[data-team-open="' + slugs[current] + '"]');
            if (link) link.focus();
          }
        }

        function step(d) {
          if (current < 0) return;
          open(slugs[(current + d + slugs.length) % slugs.length], true);
        }

        document.addEventListener("click", function (e) {
          var a = e.target.closest ? e.target.closest("[data-team-open]") : null;
          if (!a) return;
          // a modified click keeps its native meaning (new tab, new window)
          if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
          e.preventDefault();
          open(a.getAttribute("data-team-open"), true);
        });
        if (closeBtn) closeBtn.addEventListener("click", function () { close(true); });
        if (prevBtn) prevBtn.addEventListener("click", function () { step(-1); });
        if (nextBtn) nextBtn.addEventListener("click", function () { step(1); });
        // beside the panel: the dialog's own box, which is the whole viewport
        overlay.addEventListener("click", function (e) { if (e.target === overlay) close(true); });
        // Escape: the dialog would close itself; intercepted so the address follows
        overlay.addEventListener("cancel", function (e) { e.preventDefault(); close(true); });
        overlay.addEventListener("keydown", function (e) {
          if (e.key === "ArrowRight") step(1);
          else if (e.key === "ArrowLeft") step(-1);
        });

        if (!reduce && window.matchMedia("(hover: hover)").matches && window.ICON && window.ICON.cursorTilt) {
          // the panel's portrait, and the grid's cards (the news card's tilt)
          window.ICON.cursorTilt(overlay.querySelectorAll(".team-overlay__portrait"));
          window.ICON.cursorTilt(document.querySelectorAll(".team__link"));
        }

        // The grid's cards lean with the scroll the way the news rows and the
        // work tiles do (user call, Sep 2026): the SHARED engine writes one
        // --team-skew on the grid per frame; the cards consume it in the CSS.
        var grid = document.querySelector(".team__grid");
        if (grid && !reduce && window.ICON && window.ICON.velocityLean) {
          window.ICON.velocityLean(grid, grid, "--team-skew", 3);
        }

        // Back / Forward: the address is the truth
        window.addEventListener("popstate", function () {
          var m = location.pathname.match(deepLink);
          if (m && slugs.indexOf(m[1]) >= 0) open(m[1], false);
          else close(false);
        });

        // arrived at a panel's own address
        var here = location.pathname.match(deepLink);
        if (here && slugs.indexOf(here[1]) >= 0) {
          open(here[1], false);
          go("replaceState", { team: here[1] }, "", location.pathname + location.search);
        }
      })();

    },
  };
})(Drupal, once);
